"""Build a self-contained HTML executive presentation."""
from pathlib import Path
import json, html, hashlib
from datetime import datetime, timezone
BASE=Path(__file__).resolve().parent; OUT=BASE/"outputs"; OUT.mkdir(parents=True,exist_ok=True)
E=json.loads((OUT/"executive_evidence_v3.json").read_text(encoding="utf-8")); o=E["observed_outcomes"]
slides=[("Executive Question",E["executive_question"]),("Observed Outcome",f"{o['total']:,} observed people\n{o['male']} Male | {o['female']} Female | {o['unknown']} Unknown\nKnown-sex composition: {o['male_share_known']:.1%} / {o['female_share_known']:.1%}\nMale/Female ratio: {o['male_female_ratio']:.2f}:1"),("The Employment System","AI-assisted recruiting → candidate experience → human decisions → hiring → employment → opportunity → advancement"),("SIGNAL","OBSERVABLE\nPublic recruiting-environment signals can be measured descriptively."),("PREDICTION","NOT ESTIMABLE FROM PUBLIC DATA\nOnly 3 eligible matched role/month cells; no Female outcome cells. No model was fit."),("FEEDBACK","EXPLORATORY\nTemporal coverage and sample size are limited."),("Evidence Boundary","Observed disparity does not establish that Greenhouse caused it. No candidate-level posting-to-hire link is available."),("Executive Proposition","Human-AI Employment Intelligence & Governance\n\nMODEL FAIRNESS ≠ WORKFLOW FAIRNESS ≠ OUTCOME FAIRNESS"),("Publication Gate","HOLD / REVIEW REQUIRED\nLicensing, privacy, and source-permission review remain required.")]
parts=[]
for i,(title,body) in enumerate(slides,1):
    parts.append(f'<section class="slide" id="s{i}"><small>VERSION C · VERSION 3.0 · {i:02d}/{len(slides):02d}</small><h1>{html.escape(title)}</h1><p>{html.escape(body).replace(chr(10),"<br>")}</p><nav><button onclick="prev()">Previous</button><button onclick="next()">Next</button></nav></section>')
doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Version C Executive Presentation</title><style>body{margin:0;background:#f5f1e8;color:#12203c;font:20px/1.55 system-ui;display:grid;place-items:center;min-height:100vh}.slide{display:none;width:min(900px,88vw);min-height:55vh;padding:7vh 6vw;background:#fbfaf6;border-radius:24px;box-shadow:10px 10px 25px #0002,-7px -7px 20px white}.slide:first-child{display:block}small{color:#547a47;font-weight:800;letter-spacing:.1em}h1{font-size:clamp(30px,5vw,56px);line-height:1.1}p{white-space:normal}button{border:0;border-radius:20px;padding:10px 18px;background:#547a47;color:white;font-weight:700;cursor:pointer;margin-right:10px}</style>'''+'<body>'+''.join(parts)+'''<script>let i=0;const s=[...document.querySelectorAll('.slide')];function show(){s.forEach((x,n)=>x.style.display=n===i?'block':'none')}function next(){i=(i+1)%s.length;show()}function prev(){i=(i+s.length-1)%s.length;show()}document.addEventListener('keydown',e=>{if(e.key==='ArrowRight')next();if(e.key==='ArrowLeft')prev()})</script></body></html>'''
path=OUT/"VERSION_C_3_0_EXECUTIVE_PRESENTATION.html"; path.write_text(doc,encoding="utf-8")
man={"status":"BUILT_FROM_FROZEN_EVIDENCE","presentation":str(path),"sha256":hashlib.sha256(path.read_bytes()).hexdigest(),"slide_count":len(slides),"self_contained":True,"publication_status":"HOLD / REVIEW REQUIRED","github_publish_performed":False,"generated_at_utc":datetime.now(timezone.utc).isoformat()}
(OUT/"08_presentation_manifest.json").write_text(json.dumps(man,indent=2),encoding="utf-8")
print("VERSION C — 14 EXECUTIVE PRESENTATION"); print(f"STATUS: BUILT ({len(slides)} slides)"); print(f"PRESENTATION: {path}"); print(f"MANIFEST: {OUT/'08_presentation_manifest.json'}")
